-- Vault Shards (vault-shards) manifest v1
insert into public.games (id, plugin_id, name, description, repo_url, status)
values ('vault-shards', 'vault-shards', 'Vault Shards', 'A Doom-style shooter inside Obsidian: collect 7 obsidian shards and defeat The Blank Note.', null, 'listed')
on conflict (id) do update set plugin_id = excluded.plugin_id, name = excluded.name,
  description = coalesce(excluded.description, public.games.description),
  repo_url = coalesce(excluded.repo_url, public.games.repo_url), status = excluded.status;
select public.apply_manifest('vault-shards', $manifest${"gameId":"vault-shards","pluginId":"vault-shards","name":"Vault Shards","manifestVersion":1,"stats":[{"id":"runs","agg":"count","name":"Runs finished"},{"id":"wins","agg":"sum","maxDelta":1,"name":"Wins"},{"id":"deaths","agg":"sum","maxDelta":1000,"name":"Deaths"},{"id":"playtime_ms","agg":"sum","maxDelta":14400000,"name":"Play time"},{"id":"lore_pages","agg":"max","max":12,"name":"Diary pages found"},{"id":"kills","agg":"sum","maxDelta":2000},{"id":"k_quill","agg":"sum","maxDelta":2000},{"id":"k_glitch","agg":"sum","maxDelta":2000},{"id":"k_spam","agg":"sum","maxDelta":2000},{"id":"dedup","agg":"max","max":1},{"id":"max_shards","agg":"max","max":7},{"id":"k_boss","agg":"max","max":1},{"id":"max_secrets","agg":"max","max":3},{"id":"max_zones","agg":"max","max":5},{"id":"got_shotgun","agg":"max","max":1},{"id":"got_laser","agg":"max","max":1},{"id":"nodmg_shard","agg":"max","max":1},{"id":"low_hp","agg":"max","max":1},{"id":"speed","agg":"max","max":1},{"id":"flawless","agg":"max","max":1}],"leaderboards":[{"id":"fastest_win_s","name":"Fastest completion (seconds)","sort":"asc","min":60,"max":86400},{"id":"kills_per_run","name":"Most kills in one run","sort":"desc","min":0,"max":5000}],"achievements":[{"id":"first_blood","name":"First Edit","description":"Destroy your first creature of the Rot.","icon":"✏️","rule":{"stat":"kills","gte":1}},{"id":"kills50","name":"Vault Cleanup","description":"Destroy 50 enemies (across all runs).","icon":"🧹","rule":{"stat":"kills","gte":50}},{"id":"kills150","name":"Garbage Collector","description":"Destroy 150 enemies (across all runs).","icon":"♻️","rule":{"stat":"kills","gte":150}},{"id":"quill25","name":"Mightier Than the Sword","description":"Destroy 25 enemies with the Quill.","icon":"🪶","rule":{"stat":"k_quill","gte":25}},{"id":"glitch15","name":"Link Repair","description":"Destroy 15 Broken Links.","icon":"🔗","rule":{"stat":"k_glitch","gte":15}},{"id":"spam15","name":"Spam Filter","description":"Destroy 15 Spam Tags.","icon":"🚫","rule":{"stat":"k_spam","gte":15}},{"id":"dedup","name":"Deduplicated","description":"Destroy both Copies of a single Duplicate.","icon":"👯","rule":{"stat":"dedup","gte":1}},{"id":"shard1","name":"First Shard","description":"Pick up a shard of obsidian.","icon":"💎","rule":{"stat":"max_shards","gte":1}},{"id":"shard7","name":"Integrity Restored","description":"Collect all 7 shards in one run.","icon":"🔮","rule":{"stat":"max_shards","gte":7}},{"id":"boss","name":"The Void, Filled","description":"Defeat The Blank Note.","icon":"📄","rule":{"stat":"k_boss","gte":1}},{"id":"secret1","name":"Hidden File","description":"Find a secret stash.","icon":"🗝️","rule":{"stat":"max_secrets","gte":1}},{"id":"secret3","name":"Fully Indexed","description":"Find all 3 secret stashes in one run.","icon":"🔍","rule":{"stat":"max_secrets","gte":3}},{"id":"zones","name":"Cartographer","description":"Visit all 5 zones of the Vault.","icon":"🗺️","rule":{"stat":"max_zones","gte":5}},{"id":"shotgun","name":"[[Double Brackets]]","description":"Find the Wikilink Shotgun.","icon":"[[","rule":{"stat":"got_shotgun","gte":1}},{"id":"laser","name":"Linked Up","description":"Find the Graph Laser.","icon":"⚡","rule":{"stat":"got_laser","gte":1}},{"id":"pages6","name":"Chronicler","description":"Find 6 diary pages.","icon":"📜","rule":{"stat":"lore_pages","gte":6}},{"id":"pages12","name":"Keeper of Memory","description":"Find all 12 diary pages.","icon":"📚","rule":{"stat":"lore_pages","gte":12}},{"id":"nodmg","name":"Without a Single Edit","description":"Pick up a shard without taking damage since entering its zone.","icon":"🛡️","rule":{"stat":"nodmg_shard","gte":1}},{"id":"lowhp","name":"By a Thread","description":"Drop to 10 HP or less, then heal.","icon":"💔","rule":{"stat":"low_hp","gte":1}},{"id":"speed","name":"Quick Search","description":"Beat the game in under 20 minutes.","icon":"⏱️","rule":{"stat":"speed","gte":1}},{"id":"flawless","name":"No Backups Needed","description":"Beat the game without dying once.","icon":"⭐","rule":{"stat":"flawless","gte":1}}]}$manifest$::jsonb);

